mapper.select:
select
    c.id as id,
    c.error_type as errorType,
    c.vip_sign as signType,
    c.policy_no as policyNo,
    c.batch_no as batchNo,
    c.claim_no as claimNo,
    c.update_time as failTime,
    c.push_back_reason as pushBackReason,
    s.name as outInsureName,
    s.identity_type_cn as outInsureIdentityTypeCn,
    s.identity_no as outInsureIdentityNo,

    c.insure_name as insureName,
    c.insurance_name as insuranceName,
    c.branch_name as branchName,
    c.auditing_operator_name as auditingOperatorName,
    c.biz_identity_code as bizIdentityCode,
    c.tenant_id as tenantId
from ss_claim c
    left join ss_claim_stakeholder s on c.id = s.related_id and s.person_type = 'OUT_INSURE'
where c.deleted = 0
and c.pk_push_status = #{pkPushStatus}
and c.insurance_push_status = #{insurancePushStatus}

    and c.batch_no = #{batchNo}


    and c.claim_no = #{claimNo}


    and c.policy_no = #{policyNo}


    and s.name = #{outInsureName}


    and s.identity_no = #{outInsureIdentityNo}


    and c.insure_name = #{insureName}


    and c.insurance_name = #{insuranceName}


    and c.branch_name = #{branchName}


    and c.error_type = #{errorType}


    and c.auditing_operator_name = #{auditingOperatorName}


    and c.vip_sign = #{vipSign}

select
c.id as id,
c.error_type as errorType,
c.vip_sign as signType,
c.policy_no as policyNo,
c.batch_no as batchNo,
c.claim_no as claimNo,
c.update_time as failTime,
log.create_time as createTime,
c.push_back_reason as pushBackReason,
s.name as outInsureName,
s.identity_type_cn as outInsureIdentityTypeCn,
s.identity_no as outInsureIdentityNo,

c.insure_name as insureName,
c.insurance_name as insuranceName,
c.branch_name as branchName,
c.auditing_operator_name as auditingOperatorName
from claim_push_fail_operate_log log
inner join ss_claim c on log.claim_id = c.id
left join ss_claim_stakeholder s on c.id = s.related_id and s.person_type = 'OUT_INSURE'
where c.deleted = 0
and c.pk_push_status = #{pkPushStatus}
and c.insurance_push_status = #{insurancePushStatus}

    and c.batch_no = #{batchNo}


    and c.claim_no = #{claimNo}


    and c.policy_no = #{policyNo}


    and s.name = #{outInsureName}


    and s.identity_no = #{outInsureIdentityNo}


    and c.insure_name = #{insureName}


    and c.insurance_name = #{insuranceName}


    and c.branch_name = #{branchName}


    and c.error_type = #{errorType}


    and c.auditing_operator_name = #{auditingOperatorName}


    and c.vip_sign = #{vipSign}
